//! Registry-owned stable canonical refusal identities and policy classes.

/// A refusal class is policy input, never permission to replay a mutation.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RefusalClass {
    /// Fresh study premises may require a new decision.
    FreshPremise,
    /// The original operation clock expired.
    Deadline,
    /// Exact immutable identity or original inputs differ.
    Identity,
    /// A guarded generation, owner or lifetime no longer admits this operation.
    Fence,
    /// A synchronous cancellation guard refused the submitted decision.
    Cancelled,
    /// A finite declaration-owned operation bound refused admission.
    Admission,
    /// A domain or storage invariant refused the submitted operation.
    Invariant,
}
macro_rules! refusals {
    ($($variant:ident: $code:literal => ($class:ident, $message:literal)),* $(,)?) => {
        /// Closed known native THROW identities. Schema/Internal failures are not members.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        #[allow(missing_docs, reason = "each generated identity has its registry message and class")]
        pub enum RefusalCode { $($variant,)* }
        impl RefusalCode {
            /// Every declared code, for generation and exact decoder qualification.
            pub const ALL: &'static [Self] = &[$(Self::$variant,)*];
            /// Stable payload of a generated native THROW.
            pub const fn wire(self) -> &'static str { match self { $(Self::$variant => concat!("PSE_REFUSAL:", $code),)* } }
            /// Policy classification explicitly declared beside the identity.
            pub const fn class(self) -> RefusalClass { match self { $(Self::$variant => RefusalClass::$class,)* } }
            /// Human explanation; never inspected to decide policy.
            pub const fn message(self) -> &'static str { match self { $(Self::$variant => $message,)* } }
            /// Parse only a complete known code; no prefix or rendered-error search.
            pub fn parse(value: &str) -> Option<Self> { match value { $(concat!("PSE_REFUSAL:", $code) => Some(Self::$variant),)* _ => None } }
        }
        impl std::fmt::Display for RefusalCode {
            fn fmt(&self, output: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { output.write_str(self.wire()) }
        }
    };
}
